<script setup>import {onMounted,ref} from 'vue';const pets=ref([]);onMounted(async()=>{pets.value=(await (await fetch('/api/admin/pets',{credentials:'same-origin',headers:{Accept:'application/json'}})).json()).data});</script><template><v-container class="py-10"><div class="section-kicker">ADMINISTRAÇÃO</div><h1 class="text-h4 font-weight-bold mb-6">Pets e interessados</h1><v-expansion-panels variant="accordion"><v-expansion-panel v-for="pet in pets" :key="pet.id"><v-expansion-panel-title><v-icon icon="mdi-paw" class="mr-3" color="primary"/><b>{{pet.name}}</b><v-spacer/><v-chip size="small" color="primary" variant="tonal">{{pet.adoptions_count}} interessados</v-chip></v-expansion-panel-title><v-expansion-panel-text><p class="text-medium-emphasis mb-3">Doador: {{pet.owner?.name||'Não informado'}} · Fila: {{pet.queue_position||'Sem fila'}}</p><v-table><thead><tr><th>Interessado</th><th>Contato</th><th>Moradia</th><th>Status</th></tr></thead><tbody><tr v-for="adoption in pet.adoptions" :key="adoption.id"><td>{{adoption.user?.name||adoption.applicant_name}}</td><td>{{adoption.user?.email||adoption.email}}</td><td>{{adoption.housing_type}}</td><td><v-chip size="small">{{adoption.status}}</v-chip></td></tr><tr v-if="!pet.adoptions.length"><td colspan="4" class="text-center pa-4">Ainda não há interessados.</td></tr></tbody></v-table></v-expansion-panel-text></v-expansion-panel></v-expansion-panels></v-container></template>
